window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ea837cc1eb20419e"]={"versions": [{"id": "FIG-ea837cc1eb20419e", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Spezifikation des Lebenszyklus und der Übertragungszustände von Software-Paketen im Kontext der AUTOSAR Adaptive Platform. Das Diagramm modelliert das dynamische Protokollverhalten des Service-Interface <code>PackageManagement</code> der Funktionsgruppe Update and Configuration Management (UCM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Elemente:</p>\n<ul class=\"fig-list\">\n<li>Zustände: <code>TRANSFERRING</code>, <code>TRANSFERRED</code>, <code>PROCESSING</code>.</li>\n<li>Pseudozustände: <code>Initial</code> (Startknoten), <code>Final</code> (Endknoten).</li>\n<li>Service-Methoden und Trigger des Interface <code>PackageManagement</code>:</li>\n<li><code>TransferStart</code></li>\n<li><code>TransferData</code></li>\n<li><code>TransferExit</code></li>\n<li><code>ProcessSwPackage</code> (mit Guard-Bedingung <code>[CurrentStatus == READY]</code>)</li>\n<li><code>GetProcessProgress</code></li>\n<li><code>Cancel</code></li>\n<li><code>ProcessingFinished</code> (mit Aktion <code>/SwPackageProcessed</code>)</li>\n<li><code>DeleteTransfer</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beginnt im Startzustand <code>Initial</code> und wechselt über den Aufruf <code>TransferStart</code> in den Zustand <code>TRANSFERRING</code>.</p>\n<ul class=\"fig-list\">\n<li>In <code>TRANSFERRING</code> werden Blöcke des Software-Pakets über wiederholte Aufrufe der Self-Transition <code>TransferData</code> übertragen.</li>\n<li>Mit <code>TransferExit</code> wechselt das System nach <code>TRANSFERRED</code>.</li>\n<li>Aus <code>TRANSFERRED</code> führt der Methodenaufruf <code>ProcessSwPackage</code> unter der Bedingung <code>[CurrentStatus == READY]</code> in den Zustand <code>PROCESSING</code>. Alternativ kann die Sitzung über <code>DeleteTransfer</code> in den Endzustand <code>Final</code> überführt und beendet werden.</li>\n<li>In <code>PROCESSING</code> kann der Fortschritt über die Self-Transition <code>GetProcessProgress</code> abgefragt werden.</li>\n<li>Aus <code>PROCESSING</code> führt ein Abbruch über <code>Cancel</code> oder der Abschluss über <code>ProcessingFinished</code> (unter Ausführung der Aktion <code>/SwPackageProcessed</code>) zurück in den Zustand <code>TRANSFERRED</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Aufrufreihenfolge für Methoden des <code>PackageManagement</code>-Dienstes bei der Paketübertragung. Zustandsübergänge dürfen nur bei erfüllten Guards ausgeführt werden; <code>ProcessSwPackage</code> setzt voraus, dass <code>CurrentStatus</code> den Wert <code>READY</code> aufweist. Aufrufe außerhalb des definierten Zustandsfensters sind als Protokollfehler abzuweisen. Bereinigungsaktionen (<code>DeleteTransfer</code>) sind in diesem Lebenszyklus ausschließlich aus dem Zustand <code>TRANSFERRED</code> zulässig.</p>"}, {"id": "FIG-aea7db8ab0637dab", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Spezifikation des Lebenszyklus und der Übertragungszustände von Software-Paketen innerhalb eines übergeordneten Verarbeitungsrahmens im Kontext der AUTOSAR Adaptive Platform. Das Diagramm modelliert das Protokollverhalten des Service-Interface <code>PackageManagement</code> der Funktionsgruppe Update and Configuration Management (UCM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Elemente:</p>\n<ul class=\"fig-list\">\n<li>Umschließender Composite-Zustand: <code>PackagesToProcess</code>.</li>\n<li>Enthaltene Zustände: <code>TRANSFERRING</code>, <code>TRANSFERRED</code>, <code>PROCESSING</code>, <code>PROCESSED</code>.</li>\n<li>Pseudozustände: <code>Initial</code> (Startknoten), <code>Final</code> (Endknoten).</li>\n<li>Service-Methoden, Trigger und Effekte:</li>\n<li><code>TransferStart</code></li>\n<li><code>TransferData</code></li>\n<li><code>TransferExit</code></li>\n<li><code>ProcessSwPackage</code> (mit Aktion <code>/CurrentStatus == BUSY</code>)</li>\n<li><code>GetProcessProgress</code></li>\n<li><code>Cancel</code></li>\n<li><code>ProcessingFinished</code> (mit Aktion <code>/CurrentStatus == READY</code>)</li>\n<li><code>DeleteTransfer</code> (aus mehreren Zuständen)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Lebenszyklus startet im umschließenden Rahmen <code>PackagesToProcess</code> am Startknoten <code>Initial</code> und wechselt mit <code>TransferStart</code> nach <code>TRANSFERRING</code>.</p>\n<ul class=\"fig-list\">\n<li>In <code>TRANSFERRING</code> erfolgen wiederholte Nutzdatenübertragungen per Self-Transition <code>TransferData</code>. Ein vorzeitiger Abbruch ist mittels <code>DeleteTransfer</code> direkt zum Endzustand <code>Final</code> möglich.</li>\n<li>Mit <code>TransferExit</code> wird in den Zustand <code>TRANSFERRED</code> gewechselt.</li>\n<li>Aus <code>TRANSFERRED</code> löst <code>ProcessSwPackage</code> unter Setzen des Status (<code>/CurrentStatus == BUSY</code>) den Übergang nach <code>PROCESSING</code> aus. Alternativ beendet <code>DeleteTransfer</code> die Sitzung nach <code>Final</code>.</li>\n<li>Während <code>PROCESSING</code> erlaubt die Self-Transition <code>GetProcessProgress</code> Statusabfragen.</li>\n<li>Ein Abbruch über <code>Cancel</code> führt aus <code>PROCESSING</code> zurück nach <code>TRANSFERRED</code>.</li>\n<li>Reguläres Beenden der Verarbeitung über <code>ProcessingFinished</code> setzt <code>/CurrentStatus == READY</code> und wechselt in den Zustand <code>PROCESSED</code>.</li>\n<li>Aus <code>PROCESSED</code> führt der Aufruf <code>DeleteTransfer</code> in den Endzustand <code>Final</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der zulässigen Zustände und Zustandsübergänge für das Service-Interface <code>PackageManagement</code>. Die Zustandsvariablen-Setzungen (<code>/CurrentStatus == BUSY</code> bzw. <code>/CurrentStatus == READY</code>) sind während der Phasenübergänge deterministisch zu vollziehen. Der Aufruf von <code>DeleteTransfer</code> zur Bereinigung ist aus den Zuständen <code>TRANSFERRING</code>, <code>TRANSFERRED</code> sowie <code>PROCESSED</code> verbindlich vorgesehen. Eine Rückkehr nach <code>TRANSFERRED</code> erfolgt nach erfolgreicher Verarbeitung nicht mehr, sondern mündet in <code>PROCESSED</code>.</p>"}, {"id": "FIG-da6ed31b5bdec318", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Spezifikation des Lebenszyklus und der Übertragungszustände von Software-Paketen innerhalb eines übergeordneten Verarbeitungsrahmens im Kontext der AUTOSAR Adaptive Platform. Das Diagramm modelliert das Protokollverhalten des Service-Interface <code>PackageManagement</code> der Funktionsgruppe Update and Configuration Management (UCM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Elemente:</p>\n<ul class=\"fig-list\">\n<li>Umschließender Composite-Zustand: <code>PackagesToProcess</code>.</li>\n<li>Enthaltene Zustände: <code>TRANSFERRING</code>, <code>TRANSFERRED</code>, <code>PROCESSING</code>, <code>PROCESSED</code>.</li>\n<li>Pseudozustände: <code>Initial</code> (Startknoten), <code>Final</code> (Endknoten).</li>\n<li>Service-Methoden, Trigger und Effekte:</li>\n<li><code>TransferStart</code></li>\n<li><code>TransferData</code></li>\n<li><code>TransferExit</code></li>\n<li><code>ProcessSwPackage</code> (mit Aktion <code>/CurrentStatus == BUSY</code>)</li>\n<li><code>GetProcessProgress</code></li>\n<li><code>Cancel</code></li>\n<li><code>ProcessingFinished</code> (mit Aktion <code>/CurrentStatus == READY</code>)</li>\n<li><code>DeleteTransfer</code> (aus mehreren Zuständen)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Lebenszyklus startet im umschließenden Rahmen <code>PackagesToProcess</code> am Startknoten <code>Initial</code> und wechselt mit <code>TransferStart</code> nach <code>TRANSFERRING</code>.</p>\n<ul class=\"fig-list\">\n<li>In <code>TRANSFERRING</code> erfolgen wiederholte Nutzdatenübertragungen per Self-Transition <code>TransferData</code>. Ein vorzeitiger Abbruch ist mittels <code>DeleteTransfer</code> direkt zum Endzustand <code>Final</code> möglich.</li>\n<li>Mit <code>TransferExit</code> wird in den Zustand <code>TRANSFERRED</code> gewechselt.</li>\n<li>Aus <code>TRANSFERRED</code> löst <code>ProcessSwPackage</code> unter Setzen des Status (<code>/CurrentStatus == BUSY</code>) den Übergang nach <code>PROCESSING</code> aus. Alternativ beendet <code>DeleteTransfer</code> die Sitzung nach <code>Final</code>.</li>\n<li>Während <code>PROCESSING</code> erlaubt die Self-Transition <code>GetProcessProgress</code> Statusabfragen.</li>\n<li>Ein Abbruch über <code>Cancel</code> führt aus <code>PROCESSING</code> zurück nach <code>TRANSFERRED</code>.</li>\n<li>Reguläres Beenden der Verarbeitung über <code>ProcessingFinished</code> setzt <code>/CurrentStatus == READY</code> und wechselt in den Zustand <code>PROCESSED</code>.</li>\n<li>Aus <code>PROCESSED</code> führt der Aufruf <code>DeleteTransfer</code> in den Endzustand <code>Final</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der zulässigen Zustände und Zustandsübergänge für das Service-Interface <code>PackageManagement</code>. Die Zustandsvariablen-Setzungen (<code>/CurrentStatus == BUSY</code> bzw. <code>/CurrentStatus == READY</code>) sind während der Phasenübergänge deterministisch zu vollziehen. Der Aufruf von <code>DeleteTransfer</code> zur Bereinigung ist aus den Zuständen <code>TRANSFERRING</code>, <code>TRANSFERRED</code> sowie <code>PROCESSED</code> verbindlich vorgesehen. Eine Rückkehr nach <code>TRANSFERRED</code> erfolgt nach erfolgreicher Verarbeitung nicht mehr, sondern mündet in <code>PROCESSED</code>.</p>"}, {"id": "FIG-3a9f9728c30d181f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm zur Spezifikation des Lebenszyklus und der Übertragungs- sowie Verarbeitungszustände von Software-Paketen im Kontext der AUTOSAR Adaptive Platform. Das Diagramm modelliert das Protokoll- und Streaming-Verhalten des Service-Interface <code>PackageManagement</code> der Funktionsgruppe Update and Configuration Management (UCM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Elemente:</p>\n<ul class=\"fig-list\">\n<li>Zustände: <code>TRANSFERRING</code>, <code>TRANSFERRED</code>, <code>PROCESSING</code>, <code>PROCESSING_STREAM</code>, <code>PROCESSED</code>.</li>\n<li>Pseudozustände: <code>Initial</code> (Startknoten), <code>Final</code> (Endknoten).</li>\n<li>Service-Methoden, Trigger und Ereignisse:</li>\n<li><code>TransferStart</code></li>\n<li><code>TransferData</code></li>\n<li><code>TransferExit</code></li>\n<li><code>ProcessSwPackage</code></li>\n<li><code>(ProcessSwPackageDone)</code> (internes Abschlussereignis)</li>\n<li><code>Cancel</code></li>\n<li><code>Cancel | RevertProcessedSwPackages</code></li>\n<li><code>DeleteTransfer</code></li>\n<li><code>DeleteTransfer | Finish | RevertProcessedSwPackages</code></li>\n<li><code>TransferData | TransferExit</code> (kombinierte Self-Transition)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf startet am Initial-Knoten und wechselt über <code>TransferStart</code> nach <code>TRANSFERRING</code>.</p>\n<ul class=\"fig-list\">\n<li>In <code>TRANSFERRING</code> wird <code>TransferData</code> als Self-Transition ausgeführt. Aus <code>TRANSFERRING</code> bestehen drei Pfade:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>TransferExit</code> führt nach <code>TRANSFERRED</code>.</li>\n<li><code>ProcessSwPackage</code> führt direkt in den Streaming-Zustand <code>PROCESSING_STREAM</code>.</li>\n<li><code>DeleteTransfer</code> bricht ab und wechselt direkt nach <code>Final</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Im Zustand <code>PROCESSING_STREAM</code> werden Datenübertragung und Übertragungsabschluss über die Self-Transition <code>TransferData | TransferExit</code> bedient. Bei Erfolg wechselt das System über das Ereignis <code>(ProcessSwPackageDone)</code> nach <code>PROCESSED</code>. Ein Abbruch aus <code>PROCESSING_STREAM</code> erfolgt über <code>Cancel | RevertProcessedSwPackages</code> nach <code>Final</code>.</li>\n<li>Aus <code>TRANSFERRED</code> führt <code>ProcessSwPackage</code> in den Zustand <code>PROCESSING</code>, während <code>DeleteTransfer</code> nach <code>Final</code> führt.</li>\n<li>Aus <code>PROCESSING</code> führt <code>Cancel</code> zurück nach <code>TRANSFERRED</code>. Der erfolgreiche Abschluss über <code>(ProcessSwPackageDone)</code> führt nach <code>PROCESSED</code>.</li>\n<li>Aus dem Zustand <code>PROCESSED</code> wird der Endzustand <code>Final</code> über die kombinierten Alternativen <code>DeleteTransfer | Finish | RevertProcessedSwPackages</code> erreicht.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung zweier paralleler Verarbeitungsmodi für Update-Pakete: Standard-Verarbeitung nach vollständiger Übertragung (<code>TRANSFERRED</code> -> <code>PROCESSING</code>) sowie Streaming-Verarbeitung während der Datenübertragung (<code>TRANSFERRING</code> -> <code>PROCESSING_STREAM</code>). Die Bereinigung und Rückabwicklung nach <code>PROCESSED</code> bzw. <code>PROCESSING_STREAM</code> erfordert die Unterstützung von <code>RevertProcessedSwPackages</code> und <code>Finish</code>. Implementierungen des UCM müssen den parallelen Empfang von Daten im Streaming-Modus unterstützen.</p>"}], "trans": [{"from": "FIG-ea837cc1eb20419e", "to": "FIG-aea7db8ab0637dab", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Einführung des umschließenden Composite-Zustands <code>PackagesToProcess</code>.</li>\n<li>Ergänzung des neuen Folgezustands <code>PROCESSED</code>.</li>\n<li>Umleitung des Ereignisses <code>ProcessingFinished</code>: Führt von <code>PROCESSING</code> nach <code>PROCESSED</code> statt zurück nach <code>TRANSFERRED</code>.</li>\n<li>Aktualisierung der Transitionseffekte:</li>\n<li>Transition <code>ProcessSwPackage</code>: Bedingung <code>[CurrentStatus == READY]</code> entfällt, neuer Effekt <code>/CurrentStatus == BUSY</code>.</li>\n<li>Transition <code>ProcessingFinished</code>: Effekt <code>/SwPackageProcessed</code> wird ersetzt durch <code>/CurrentStatus == READY</code>.</li>\n<li>Zusätzliche Transitionen zum Endzustand <code>Final</code>:</li>\n<li>Neue Transition <code>DeleteTransfer</code> direkt aus <code>TRANSFERRING</code>.</li>\n<li>Neue Transition <code>DeleteTransfer</code> aus <code>PROCESSED</code>.</li>\n</ul>"}, {"from": "FIG-aea7db8ab0637dab", "to": "FIG-da6ed31b5bdec318", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-da6ed31b5bdec318", "to": "FIG-3a9f9728c30d181f", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Der umschließende Composite-Zustand <code>PackagesToProcess</code> entfällt; der Pseudozustand <code>Initial</code> liegt links von <code>TRANSFERRING</code>.</li>\n<li>Neuer Zustand <code>PROCESSING_STREAM</code> für Streaming-Verarbeitung.</li>\n<li>Neue Transition <code>ProcessSwPackage</code> direkt aus <code>TRANSFERRING</code> nach <code>PROCESSING_STREAM</code>.</li>\n<li>Self-Transition an <code>PROCESSING_STREAM</code> für fortlaufenden Empfang und Abschluss der Übertragung: <code>TransferData | TransferExit</code>.</li>\n<li>Transition von <code>PROCESSING_STREAM</code> nach <code>PROCESSED</code> getriggert durch <code>(ProcessSwPackageDone)</code>.</li>\n<li>Neue Abbruch-Transition von <code>PROCESSING_STREAM</code> nach <code>Final</code> via <code>Cancel | RevertProcessedSwPackages</code>.</li>\n<li>Transition von <code>PROCESSING</code> nach <code>PROCESSED</code>: Trigger umbenannt von <code>ProcessingFinished</code> zu <code>(ProcessSwPackageDone)</code>.</li>\n<li>Entfernung von <code>GetProcessProgress</code> (Self-Transition an <code>PROCESSING</code>).</li>\n<li>Entfernung der Status-Zuweisungseffekte (<code>/CurrentStatus == BUSY</code> an <code>ProcessSwPackage</code>, <code>/CurrentStatus == READY</code> an <code>ProcessingFinished</code>).</li>\n<li>Erweiterte Transition von <code>PROCESSED</code> nach <code>Final</code>: Trigger erweitert um alternative Aufrufe <code>DeleteTransfer | Finish | RevertProcessedSwPackages</code>.</li>\n</ul>"}]};
